def apply_approval(
    proposal: ChangeProposal,
    response: ApprovalResponse,
) -> ChangeProposal:
    """
    Apply a human approval decision to the proposal.

    This does NOT modify repository files.
    """

    if (
        response.proposal_id
        != proposal.proposal_id
    ):
        raise ApprovalError(
            "Approval response does not match "
            "the proposal."
        )

    if proposal.status != ChangeStatus.VALIDATED:
        raise ApprovalError(
            "Only validated proposals can "
            "receive approval."
        )

    if response.decision == (
        ApprovalDecision.APPROVE
    ):
        proposal.status = (
            ChangeStatus.APPROVED
        )

    elif response.decision == (
        ApprovalDecision.REJECT
    ):
        proposal.status = (
            ChangeStatus.REJECTED
        )

    else:
        raise ApprovalError(
            f"Unsupported approval decision: "
            f"{response.decision}"
        )

    if response.comment:
        proposal.metadata[
            "approval_comment"
        ] = response.comment

    proposal.metadata[
        "approval_decision"
    ] = response.decision.value

    return proposal

