def evaluate_investigation(
    *,
    intent: str,
    evidence: list[dict[str, Any]],
    executed_tools: list[str],
    current_step: int,
    max_steps: int,
) -> InvestigationEvaluation:
    """
    Deterministically decide whether the investigation
    should continue or finish.

    The evaluator does not use an LLM.

    It uses:
    - query intent
    - collected evidence
    - executed tools
    - remaining investigation steps
    """

    # ---------------------------------------------------------
    # No more planned tools
    # ---------------------------------------------------------
    if current_step >= max_steps:
        return InvestigationEvaluation(
            decision=COMPLETE,
            reason="All planned investigation steps have been executed.",
        )

    # ---------------------------------------------------------
    # Reference search
    # ---------------------------------------------------------
    if intent == "reference_search":
        if _has_evidence_from_tool(
            evidence,
            "reference_search",
        ):
            return InvestigationEvaluation(
                decision=COMPLETE,
                reason=(
                    "Reference evidence was found; "
                    "the requested symbol references have been investigated."
                ),
            )

        return InvestigationEvaluation(
            decision=CONTINUE,
            reason=(
                "Reference evidence has not been collected yet; "
                "continue the investigation."
            ),
        )

    # ---------------------------------------------------------
    # Test discovery
    # ---------------------------------------------------------
    if intent == "test_discovery":
        if _has_evidence_from_tool(
            evidence,
            "test_search",
        ):
            return InvestigationEvaluation(
                decision=COMPLETE,
                reason=(
                    "Relevant test evidence was collected."
                ),
            )

        return InvestigationEvaluation(
            decision=CONTINUE,
            reason=(
                "Test evidence has not been collected yet."
            ),
        )

    # ---------------------------------------------------------
    # Configuration
    # ---------------------------------------------------------
    if intent == "configuration":
        if _has_evidence_from_tool(
            evidence,
            "configuration_search",
        ):
            return InvestigationEvaluation(
                decision=COMPLETE,
                reason=(
                    "Configuration evidence was collected."
                ),
            )

        return InvestigationEvaluation(
            decision=CONTINUE,
            reason=(
                "Configuration evidence has not been collected yet."
            ),
        )

    # ---------------------------------------------------------
    # Entrypoint discovery
    # ---------------------------------------------------------
    if intent == "entrypoint_discovery":
        if _has_evidence_from_tool(
            evidence,
            "entrypoint_search",
        ):
            return InvestigationEvaluation(
                decision=COMPLETE,
                reason=(
                    "Entrypoint evidence was collected."
                ),
            )

        return InvestigationEvaluation(
            decision=CONTINUE,
            reason=(
                "Entrypoint evidence has not been collected yet."
            ),
        )

    # ---------------------------------------------------------
    # Symbol lookup
    # ---------------------------------------------------------
    if intent == "symbol_lookup":
        if _has_evidence_from_tool(
            evidence,
            "symbol_search",
        ):
            return InvestigationEvaluation(
                decision=COMPLETE,
                reason=(
                    "The requested symbol was located."
                ),
            )

        return InvestigationEvaluation(
            decision=CONTINUE,
            reason=(
                "The requested symbol has not been located yet."
            ),
        )

    # ---------------------------------------------------------
    # Function explanation
    # ---------------------------------------------------------
    if intent == "function_explanation":
        if _has_evidence_from_tool(
            evidence,
            "symbol_search",
        ) and _has_evidence_from_tool(
            evidence,
            "repository_search",
        ):
            return InvestigationEvaluation(
                decision=COMPLETE,
                reason=(
                    "Function implementation and repository context "
                    "have been collected."
                ),
            )

        return InvestigationEvaluation(
            decision=CONTINUE,
            reason=(
                "More implementation or repository context "
                "is required."
            ),
        )

    # ---------------------------------------------------------
    # Architecture
    # ---------------------------------------------------------
    if intent == "architecture":
        if _has_evidence_from_tool(
            evidence,
            "repository_search",
        ):
            return InvestigationEvaluation(
                decision=COMPLETE,
                reason=(
                    "Repository architecture evidence was collected."
                ),
            )

        return InvestigationEvaluation(
            decision=CONTINUE,
            reason=(
                "Architecture evidence has not been collected yet."
            ),
        )

    # ---------------------------------------------------------
    # Dependency search
    # ---------------------------------------------------------
    if intent == "dependency_search":
        if _has_evidence_from_tool(
            evidence,
            "repository_search",
        ):
            return InvestigationEvaluation(
                decision=COMPLETE,
                reason=(
                    "Dependency-related repository evidence was collected."
                ),
            )

        return InvestigationEvaluation(
            decision=CONTINUE,
            reason=(
                "Dependency evidence has not been collected yet."
            ),
        )

    # ---------------------------------------------------------
    # General search
    # ---------------------------------------------------------
    if intent == "general_search":
        if evidence:
            return InvestigationEvaluation(
                decision=COMPLETE,
                reason=(
                    "Relevant repository evidence was collected."
                ),
            )

        return InvestigationEvaluation(
            decision=CONTINUE,
            reason=(
                "No evidence has been collected yet."
            ),
        )

    # ---------------------------------------------------------
    # Generic fallback
    # ---------------------------------------------------------
    if evidence:
        return InvestigationEvaluation(
            decision=COMPLETE,
            reason=(
                "Evidence was collected for the investigation."
            ),
        )

    return InvestigationEvaluation(
        decision=CONTINUE,
        reason=(
            "No evidence has been collected; "
            "continue investigating."
        ),
    )

def evaluate_current_investigation(
    state: dict[str, Any],
) -> dict[str, Any]:
    """
    Evaluate whether the investigation should continue.
    """

    from app.agent.evaluator import (
        COMPLETE,
        evaluate_investigation,
    )

    evaluation = evaluate_investigation(
        intent=state.get(
            "intent",
            "general_search",
        ),
        evidence=state.get(
            "evidence",
            [],
        ),
        executed_tools=state.get(
            "executed_tools",
            [],
        ),
        current_step=state.get(
            "current_step",
            0,
        ),
        max_steps=state.get(
            "max_steps",
            0,
        ),
    )

    state["investigation_decision"] = (
        evaluation.decision
    )

    state["investigation_reason"] = (
        evaluation.reason
    )

    if evaluation.decision == COMPLETE:

        state["needs_more_investigation"] = False
        state["investigation_complete"] = True

    else:

        state["needs_more_investigation"] = True
        state["investigation_complete"] = False

    return state

def _has_evidence_from_tool(
    evidence: list[dict[str, Any]],
    tool_name: str,
) -> bool:
    """
    Check whether at least one evidence item came from
    the specified investigation tool.
    """

    return any(
        item.get("source_tool") == tool_name
        for item in evidence
    )

class EvaluationRunner:
    """Evaluation runner with backward-compatible strict scoring and v2 diagnostics."""

    def __init__(self, retriever: Retriever, *, top_k: int = 5) -> None:
        if top_k < 1:
            raise ValueError("top_k must be at least 1.")
        self.retriever = retriever
        self.top_k = top_k
        try:
            params = inspect.signature(retriever).parameters
            self._supports_top_k = "top_k" in params or any(
                p.kind == inspect.Parameter.VAR_KEYWORD for p in params.values()
            )
        except (TypeError, ValueError):
            self._supports_top_k = False

    def _retrieve(self, case: EvaluationCase) -> list[dict[str, Any]]:
        if self._supports_top_k:
            return self.retriever(case.repository_id, case.query, top_k=self.top_k)
        return self.retriever(case.repository_id, case.query)

    def evaluate_case(self, case: EvaluationCase) -> EvaluationResult:
        start = perf_counter()
        try:
            results = self._retrieve(case)
            latency_ms = (perf_counter() - start) * 1000.0
            expected = list(case.expected_evidence)
            actual_intent = getattr(results, "intent", None)
            if actual_intent is not None and not isinstance(actual_intent, str):
                actual_intent = str(getattr(actual_intent, "name", actual_intent))
            expected_intent = case.expected_intent
            intent_accuracy = (
                float(actual_intent == expected_intent)
                if expected_intent is not None and actual_intent is not None
                else None
            )

            if not expected:
                metrics = {"hit_at_k": 1.0, "latency_ms": latency_ms}
                if intent_accuracy is not None:
                    metrics["intent_accuracy"] = intent_accuracy
                return EvaluationResult(
                    case_id=case.case_id, task=case.task, passed=True,
                    score=1.0, metrics=metrics,
                    expected={"evidence": expected, "intent": expected_intent},
                    actual={"results": results, "intent": actual_intent},
                )

            hit_score = sum(hit_at_k(results, item, self.top_k) for item in expected) / len(expected)
            precision = precision_at_k(results, expected, self.top_k)
            recall = recall_at_k(results, expected, self.top_k)
            mrr = mean_reciprocal_rank([(results[:self.top_k], expected)])
            score = (hit_score + precision + recall + mrr) / 4

            metrics = {
                "hit_at_k": hit_score,
                "precision_at_k": precision,
                "recall_at_k": recall,
                "mrr": mrr,
                "file_hit_at_1": file_hit_at_k(results, expected, 1),
                "file_hit_at_5": file_hit_at_k(results, expected, 5),
                "file_hit_at_10": file_hit_at_k(results, expected, 10),
                "strict_evidence_hit_at_10": strict_evidence_hit_at_k(results, expected, 10),
                "file_mrr_at_10": file_reciprocal_rank_at_k(results, expected, 10),
                "latency_ms": latency_ms,
            }
            if intent_accuracy is not None:
                metrics["intent_accuracy"] = intent_accuracy

            return EvaluationResult(
                case_id=case.case_id, task=case.task, passed=score >= 0.5,
                score=score, metrics=metrics,
                expected={"evidence": expected, "intent": expected_intent},
                actual={"results": results, "intent": actual_intent},
            )
        except Exception as exc:
            return EvaluationResult(
                case_id=case.case_id, task=case.task, passed=False,
                score=0.0, errors=[str(exc)],
                metrics={"latency_ms": (perf_counter() - start) * 1000.0},
            )

    def evaluate(self, cases: list[EvaluationCase]) -> EvaluationReport:
        results = [self.evaluate_case(case) for case in cases]
        total = len(results)
        passed = sum(1 for result in results if result.passed)
        overall_score = sum(result.score for result in results) / total if total else 0.0
        metric_names = (
            "hit_at_k", "precision_at_k", "recall_at_k", "mrr",
            "file_hit_at_1", "file_hit_at_5", "file_hit_at_10",
            "strict_evidence_hit_at_10", "file_mrr_at_10",
            "intent_accuracy", "latency_ms",
        )
        aggregate_metrics: dict[str, float] = {}
        for name in metric_names:
            values = [result.metrics[name] for result in results if name in result.metrics]
            aggregate_metrics[name] = sum(values) / len(values) if values else 0.0
        return EvaluationReport(
            total_cases=total, passed_cases=passed, failed_cases=total-passed,
            overall_score=overall_score, results=results, metrics=aggregate_metrics,
        )

