    # ---------------------------------------------------------
    if intent == "architecture":
        if _has_evidence_from_tool(
            evidence,
            "repository_search",
        ):
            return InvestigationEvaluation(
                decision=COMPLETE,
                reason=(
                    "Repository architecture evidence was collected."
                ),
            )

