def _safe_float(value: Any) -> float | None:
    """
    Convert a value to float when possible.
    """

    if value is None:
        return None

    try:
        return float(value)
    except (TypeError, ValueError):
        return None

def add_evidence(
    evidence_store: list[dict[str, Any]],
    results: list[dict[str, Any]],
    *,
    repository_id: str,
    source_tool: str,
) -> list[dict[str, Any]]:
    """
    Normalize and add search results to the evidence store.

    Duplicate evidence is ignored.
    """

    existing_ids = {
        item.get("evidence_id")
        for item in evidence_store
    }

    for result in results:
        evidence = normalize_evidence(
            result,
            repository_id=repository_id,
            source_tool=source_tool,
        )

        if evidence.evidence_id in existing_ids:
            continue

        evidence_store.append(
            evidence_to_dict(evidence)
        )

        existing_ids.add(
            evidence.evidence_id
        )

    return evidence_store

def evidence_to_dict(
    evidence: Evidence,
) -> dict[str, Any]:
    """
    Convert Evidence into a JSON/state-friendly dictionary.
    """

    return asdict(evidence)

def _safe_int(value: Any) -> int | None:
    """
    Convert a value to int when possible.
    """

    if value is None:
        return None

    try:
        return int(value)
    except (TypeError, ValueError):
        return None

